<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
use VCX\Parity\{Store,Importer,ControlTower,Seeder};
use VCX\Core\Database;
Store::check(str_ends_with(getenv('DB_DATABASE')?:'','_test'),'Isolated test database required');
$db=Database::connect();$name='vcx_import_'.bin2hex(random_bytes(5)).'_test';$checks=0;
function check(bool $v,string $msg): void {global$checks;if(!$v)throw new RuntimeException($msg);$checks++;echo'PASS migration '.$msg."\n";}
try{
    $db->exec('CREATE DATABASE `'.$name.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_bin');$db->exec('USE `'.$name.'`');foreach(explode(';',file_get_contents(dirname(__DIR__).'/database/migrations/001_parity.sql'))as$sql)if(trim($sql))$db->exec($sql);$s=new Store($db);$i=new Importer();$sample=$i->read(dirname(__DIR__).'/database/seed.json');
    check(!$i->validate($sample),'valid sample and repeated template IDs');$duplicateStep=$sample;$duplicateStep['tables']['PROCEDURE_TEMPLATES'][]=$duplicateStep['tables']['PROCEDURE_TEMPLATES'][0];check(!$i->validate($duplicateStep),'duplicate template step numbers retain GAS semantics');check(!$s->rows('TASKS'),'dry-run has zero database writes');
    $db->exec("CREATE TRIGGER fail_import BEFORE INSERT ON issues FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic failure'");$thrown=false;try{$i->apply($s,$sample);}catch(PDOException $e){$thrown=true;}check($thrown,'injected failure surfaces');$s->invalidate();foreach(array_keys($s->schema)as$table)check(!$s->rows($table),'rollback clears '.$table);$db->exec('DROP TRIGGER fail_import');
    $i->apply($s,$sample);$export=$s->transaction(fn()=>$i->export($s),false);check(Importer::fingerprint($sample)===Importer::fingerprint($export),'export/import preserves every ID, value, relationship and row order');
    $retry=$i->apply($s,$sample);check(!empty($retry['resumed']),'completed import retry is terminal/idempotent');$different=$sample;$different['tables']['PROJECTS'][0]['Project_Name']='Different';$rejected=false;try{$i->apply($s,$different);}catch(RuntimeException $e){$rejected=true;}check($rejected,'different import refuses nonempty target');
    $fkRejected=false;try{$s->transaction(fn()=>$s->put('ASSIGNMENTS',['Assignment_ID'=>'BAD','Task_ID'=>'missing','User_ID'=>'PIC']));}catch(PDOException $e){$fkRejected=true;}check($fkRejected,'foreign key constraint rejects orphan');
    $legacy=$sample;$legacy['schemaVersion']='LEGACY_V1';$legacy['tables']['CONFIG'][0]['Value']='LEGACY_V1';$legacy['tables']['TASKS']=[];$legacy['tables']['PHASES']=[];$legacy['tables']['ASSIGNMENTS']=[];$legacy['tables']['CHECKLIST_ITEMS']=[];$legacy['tables']['ISSUES']=[];
    $phase=array_fill_keys($s->schema['PHASES'],'');$phase=array_merge($phase,['Phase_ID'=>'LEGACY-PHASE','Project_ID'=>'DEMO-PRJ-01','Phase_Name'=>'Phase','Phase_Order'=>'1','Status'=>'In Progress','RAG'=>'Green']);$legacy['tables']['PHASES'][]=$phase;
    foreach(['Summary','Task','Milestone']as$n=>$type){$t=array_fill_keys($s->schema['TASKS'],'');$legacy['tables']['TASKS'][]=array_merge($t,['Task_ID'=>'L-'.$n,'Project_ID'=>'DEMO-PRJ-01','Task_Name'=>$type,'Task_Type'=>$type,'Parent_Task_ID'=>$n===1?'L-0':'','Phase_ID'=>'LEGACY-PHASE','Progress'=>'0','Status'=>'Not Started','RAG'=>'Green','Start_Date'=>'2026-11-15','End_Date'=>'2026-11-15']);}
    check(!$i->validate($legacy),'legacy snapshot validates');$plan=$i->plan($legacy);check(!$plan['errors'],'legacy migration plan validates');check(in_array('SUMMARY_NORMALIZED_TO_TASK',array_column($plan['warnings'],'code'),true),'legacy summary warning reported');$unified=$plan['target'];check(!$i->validate($unified),'legacy-to-unified result validates');check($unified['tables']['TASKS'][0]['Parent_Task_ID']==='TSK-PHASE-LEGACY-PHASE','legacy phase task mapping');check($unified['tables']['TASKS'][1]['Parent_Task_ID']==='L-0','legacy child ID preserved');check($unified['tables']['TASKS'][2]['Task_Type']==='MILESTONE','legacy milestone preserved');
    // CSV roundtrip includes commas, quotes, newlines and UTF-8 BOM.
    $temp=sys_get_temp_dir().'/pmo-csv-'.bin2hex(random_bytes(6));mkdir($temp,0700);$sample['tables']['PROJECTS'][0]['Objective']="Tiếng Việt, \"quoted\"\nsecond line";
    try{foreach($s->schema as$table=>$cols){$f=fopen($temp.'/'.$table.'.csv','w');fwrite($f,"\xEF\xBB\xBF");$columns=$table==='TASKS'?array_merge($cols,['Sort_Order']):$cols;fputcsv($f,$columns,',','"','');foreach($sample['tables'][$table]as$r)fputcsv($f,array_map(fn($k)=>$r[$k],$columns),',','"','');fclose($f);}$roundtrip=$i->read($temp);check(Importer::fingerprint($sample)===Importer::fingerprint($roundtrip),'CSV BOM/multiline/quotes roundtrip');$f=fopen($temp.'/TASKS.csv','a');fputcsv($f,['too','few'],',','"','');fclose($f);$rejected=false;try{$i->read($temp);}catch(RuntimeException $e){$rejected=true;}check($rejected,'CSV wrong row width rejected');}finally{foreach(glob($temp.'/*')as$f)unlink($f);rmdir($temp);}
    $db->beginTransaction();try{
        // A second empty schema checks the clean-pilot -> seed workflow without rewriting accounts/config/calendar/templates.
        $seedName=$name.'_seed';$db->exec('CREATE DATABASE `'.$seedName.'` CHARACTER SET utf8mb4 COLLATE utf8mb4_bin');$db->exec('USE `'.$seedName.'`');foreach(explode(';',file_get_contents(dirname(__DIR__).'/database/migrations/001_parity.sql'))as$sql)if(trim($sql))$db->exec($sql);$seedStore=new Store($db);$seedStore->put('USERS',['User_ID'=>'PRESERVED-ADMIN','Full_Name'=>'Preserved Admin','Email'=>'admin@example.invalid','Active'=>'TRUE','System_Role'=>'PMO_ADMIN']);$seedStore->config('DATABASE_SCHEMA_VERSION','UNIFIED_TASKS_V2');$before=$seedStore->rows('USERS');$result=(new Seeder())->seed($seedStore);check($result['tasks']===210,'clean pilot synthetic seed creates full task tree');check($seedStore->rows('USERS')===$before,'clean pilot seed preserves existing users');check(!$seedStore->rows('AUTH_USERS')&&!$seedStore->rows('CALENDAR')&&!$seedStore->rows('PROCEDURE_TEMPLATES'),'clean pilot seed preserves accounts calendar templates');check(!$i->validate($i->export($seedStore)),'clean pilot seeded relationships validate');$rejected=false;try{(new Seeder())->seed($seedStore);}catch(RuntimeException $e){$rejected=true;}check($rejected,'seed cannot run twice');
    }finally{if($db->inTransaction())$db->rollBack();$db->exec('USE `'.$name.'`');if(isset($seedName))$db->exec('DROP DATABASE IF EXISTS `'.$seedName.'`');}
    echo Store::json(['passed'=>$checks,'failed'=>0])."\n";
}finally{$db->exec('DROP DATABASE IF EXISTS `'.$name.'`');}
